package com.azuki.htmlai;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class MainActivity extends Activity{
 final String MODEL="openai/gpt-oss-120b",PREF="html_ai"; final ExecutorService io=Executors.newSingleThreadExecutor();
 int bg=0xff10141d,panel=0xff202938,green=0xff69e3a2; LinearLayout root,body; EditText code,input; TextView info; WebView web; JSONArray projects=new JSONArray(),chat=new JSONArray(); JSONObject current; String screen="home";
 String key(){return getSharedPreferences(PREF,0).getString("key","");} void key(String s){getSharedPreferences(PREF,0).edit().putString("key",s).apply();}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);try{projects=new JSONArray(getSharedPreferences(PREF,0).getString("projects","[]"));}catch(Exception e){}if(key().isEmpty())setup();else home();}
 TextView t(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackground(shape(panel));return b;}
 GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(18);return d;}
 void base(String name){screen=name;root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,14,18,14);root.setBackgroundColor(bg);setContentView(root);LinearLayout top=new LinearLayout(this);TextView brand=t("HTML AI",20,green);brand.setTypeface(null,1);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));Button st=btn("Settings");top.addView(st);st.setOnClickListener(v->settings());root.addView(top);root.addView(t(name,25,-1));ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,12,0,12);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
 void setup(){base("Connect Groq");body.addView(t("Enter your Groq API key to get started.",16,0xffb8c2d1));EditText k=new EditText(this);k.setSingleLine();k.setHint("gsk_...");k.setTextColor(-1);k.setInputType(129);k.setBackground(shape(panel));body.addView(k);Button go=btn("Validate and continue");body.addView(go);info=t("",14,green);body.addView(info);go.setOnClickListener(v->{String s=k.getText().toString().trim();info.setText("Validating...");io.execute(()->{boolean ok=valid(s);runOnUiThread(()->{if(ok){key(s);home();}else info.setText("Invalid key or network error.");});});});body.addView(t("The key is saved privately on this device.",12,0xff9ba8ba));}
 boolean valid(String k){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://api.groq.com/openai/v1/models").openConnection();c.setRequestProperty("Authorization","Bearer "+k);c.setConnectTimeout(12000);return c.getResponseCode()==200;}catch(Exception e){return false;}finally{if(c!=null)c.disconnect();}}
 void save(){getSharedPreferences(PREF,0).edit().putString("projects",projects.toString()).apply();}
 void home(){base("Projects");Button add=btn("+ New project");body.addView(add);add.setOnClickListener(v->newProject());for(int i=0;i<projects.length();i++){final JSONObject p=projects.optJSONObject(i);if(p==null)continue;Button b=btn(p.optString("name","Untitled")+"  ·  Open");body.addView(b);b.setOnClickListener(v->{current=p;chat=new JSONArray();editor();});}}
 void newProject(){EditText n=new EditText(this);n.setHint("Project name");new AlertDialog.Builder(this).setTitle("New project").setView(n).setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->{try{String name=n.getText().toString().trim();if(name.isEmpty())name="My website";current=new JSONObject().put("name",name).put("html","<!doctype html>\n<html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>"+name+"</title></head><body><h1>Hello world!</h1></body></html>");projects.put(current);save();chat=new JSONArray();editor();}catch(Exception e){}}).show();}
 void nav(){LinearLayout row=new LinearLayout(this);for(String s:new String[]{"Editor","AI Chat","Preview"}){Button b=btn(s);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{if(s.equals("Editor"))editor();else if(s.equals("AI Chat"))chatScreen();else preview();});}root.addView(row,2);}
 void editor(){base(current.optString("name","Project"));nav();body.addView(t("index.html",13,green));code=new EditText(this);code.setGravity(Gravity.TOP);code.setTextColor(-1);code.setTextSize(13);code.setTypeface(Typeface.MONOSPACE);code.setMinLines(16);code.setPadding(12,12,12,12);code.setBackground(shape(panel));code.setText(current.optString("html",""));body.addView(code,new LinearLayout.LayoutParams(-1,0,1));Button save=btn("Save HTML");body.addView(save);save.setOnClickListener(v->{saveCode();Toast.makeText(this,"Saved",0).show();});}
 void saveCode(){if(code!=null)try{current.put("html",code.getText().toString());save();}catch(Exception e){}}
 void chatScreen(){base("AI Chat");nav();body.addView(t("Describe what to build or change. Chat context stays active while this project is open.",13,0xffb8c2d1));info=t("",14,green);body.addView(info);input=new EditText(this);input.setTextColor(-1);input.setHintTextColor(0xffaab4c4);input.setHint("Ask AI to create or edit your HTML...");input.setBackground(shape(panel));body.addView(input);Button send=btn("Send");body.addView(send);send.setOnClickListener(v->{String q=input.getText().toString().trim();if(q.isEmpty())return;input.setText("");try{chat.put(new JSONObject().put("role","user").put("content",q));}catch(Exception e){}info.setText("Thinking...");io.execute(()->ask(info));});}
 void ask(TextView label){HttpURLConnection c=null;try{JSONArray m=new JSONArray();m.put(new JSONObject().put("role","system").put("content","You are an expert web developer. Modify current index.html according to the user's request. Return the COMPLETE updated HTML in one fenced html code block. Preserve existing features unless asked to change them."));for(int i=0;i<chat.length();i++)m.put(chat.getJSONObject(i));m.put(new JSONObject().put("role","user").put("content","Current index.html:\n"+current.optString("html")+"\nPlease apply my latest request."));JSONObject data=new JSONObject().put("model",MODEL).put("messages",m).put("temperature",0.4);c=(HttpURLConnection)new URL("https://api.groq.com/openai/v1/chat/completions").openConnection();c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+key());c.setRequestProperty("Content-Type","application/json");c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setDoOutput(true);c.getOutputStream().write(data.toString().getBytes("UTF-8"));int status=c.getResponseCode();InputStream in=status<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);JSONObject res=new JSONObject(out.toString("UTF-8"));if(status>=400)throw new Exception(res.optJSONObject("error").optString("message","Groq request failed"));String answer=res.getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content");String html=extract(answer);if(html!=null){current.put("html",html);save();}chat.put(new JSONObject().put("role","assistant").put("content",answer));runOnUiThread(()->label.setText(html==null?"AI replied, but no HTML code block was returned. Ask it to provide complete HTML.":"index.html updated and saved. Open Editor or Preview."));}catch(Exception e){runOnUiThread(()->label.setText("Error: "+e.getMessage()));}finally{if(c!=null)c.disconnect();}}
 String extract(String s){int a=s.indexOf("\`\`\`");if(a<0)return null;int b=s.indexOf('\n',a);if(b<0)return null;int z=s.indexOf("\`\`\`",b+1);if(z<0)return null;String lang=s.substring(a+3,b).trim().toLowerCase();if(!lang.isEmpty()&&!lang.contains("html"))return null;return s.substring(b+1,z).trim();}
 void preview(){saveCode();base("Preview");nav();web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);body.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.loadDataWithBaseURL(null,current.optString("html",""),"text/html","UTF-8",null);Button refresh=btn("Refresh");body.addView(refresh);refresh.setOnClickListener(v->web.loadDataWithBaseURL(null,current.optString("html",""),"text/html","UTF-8",null));}
 void settings(){base("Settings");EditText k=new EditText(this);k.setText(key());k.setTextColor(-1);k.setInputType(129);k.setBackground(shape(panel));body.addView(t("Groq API key",14,0xffb8c2d1));body.addView(k);Button save=btn("Save key");body.addView(save);save.setOnClickListener(v->{String s=k.getText().toString().trim();if(!s.isEmpty()){key(s);home();}});Button back=btn("Back to projects");body.addView(back);back.setOnClickListener(v->home());}
 @Override public void onBackPressed(){home();}
 @Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}